// The workspace ROOT is itself a worktree of this dedicated repo on the same
// <user>/<workspace> branch as the repo worktrees inside it. Everything
// durable — .sandbox/workspace.yml, .sandbox/notes/, the projected .claude/
// and generated context files — gets git history and a push target. The
// repo's main holds only the scaffold (README, .gitignore, starting
// .claude), so there is no unrelated content to contend with on feature
// branches. `sandbox workspace` consumes the checkout; `sandbox setup`
// clones/updates it.
// WHICH repo that is, is machine config (`overrides.workspace_repo`): a solo
// developer uses their own, a team points every machine at one shared
// <org>/sandbox-workspace. Only the local directory name is fixed — the
// checkout always lands at repos_root/sandbox-workspace, whatever it is named
// on GitHub, so the consumers below can keep looking in one place.
export const WORKSPACE_ROOT_REPO = "sandbox-workspace";

export function workspaceRepoUrl(slug: string): string {
  return `https://github.com/${slug}.git`;
}

/** A GitHub login: alphanumerics and dashes, nothing else. */
const isLogin = (s: string): boolean => /^[A-Za-z0-9-]+$/.test(s);

/**
 * The authenticated GitHub login, or "" when `gh` is absent or logged out.
 *
 * Asks `gh` rather than git config: the answer must be a real GitHub login for
 * the clone URL to work, and `user.name` is a display name, not a login.
 */
export function githubUser(runner: Runner = defaultRunner): string {
  const [rc, out] = runner(["gh", "api", "user", "-q", ".login"]);
  const login = out.trim().split("\n").pop()?.trim() ?? "";
  return rc === 0 && isLogin(login) ? login : "";
}

/**
 * Every owner this user can push under: their own login first, then their orgs.
 *
 * The wizard offers these as choices, which is the whole point of asking gh —
 * an org's `sandbox-workspace` is a name you have to know, and mistyping it
 * produces a clone failure three steps later. Empty when gh can't answer, and
 * callers must stay usable then: nothing here is a hard prerequisite.
 */
export function githubOwners(runner: Runner = defaultRunner): string[] {
  const user = githubUser(runner);
  if (!user) {
    return [];
  }
  const [rc, out] = runner(["gh", "api", "user/orgs", "--paginate", "-q", ".[].login"]);
  const orgs =
    rc === 0
      ? out
          .split("\n")
          .map((l) => l.trim())
          .filter((l) => isLogin(l) && l !== user)
      : [];
  return [user, ...orgs];
}

/** `<github user>/sandbox-workspace`, or "" when the login can't be resolved. */
export function defaultWorkspaceRepo(runner: Runner = defaultRunner): string {
  const user = githubUser(runner);
  return user ? `${user}/${WORKSPACE_ROOT_REPO}` : "";
}

// The demo registry's two apps (backend, frontend) live here, checked out
// alongside `sandbox` under repos_root so workspaces can worktree it. Cloned
// only when setup seeds the demo registry — someone bringing their own
// services.yaml has no use for it, and `sandbox setup` should not litter
// repos_root with a repo they'll never open.
export const DEMO_SERVICES_REPO = "demo-services";
export const DEMO_SERVICES_REPO_URL = "git@github.com:jbbz-sandbox/demo-services.git";

/** A repo `sandbox setup` keeps checked out under repos_root. */
interface RepoSpec {
  name: string;
  url: string;
  /** Appended to the unreachable-clone message: what breaks without it. */
  missingConsequence: string;
}

const workspaceRootSpec = (slug: string): RepoSpec => ({
  name: WORKSPACE_ROOT_REPO,
  url: workspaceRepoUrl(slug),
  missingConsequence: "Workspaces will fall back to plain directories.",
});

const DEMO_SERVICES_SPEC: RepoSpec = {
  name: DEMO_SERVICES_REPO,
  url: DEMO_SERVICES_REPO_URL,
  missingConsequence: "The demo backend/frontend services will not start until it is cloned there.",
};

function defaultRunner(cmd: string[]): [number, string] {
  let res;
  try {
    res = run(cmd, { capture: true, timeout: 300 });
  } catch (e) {
    if (e instanceof ProcError && e.code === "ENOENT") {
      return [127, `${cmd[0]}: command not found`];
    }
    if (e instanceof ProcError && e.code === "ETIMEDOUT") {
      return [124, `${cmd.join(" ")}: timed out after 300s`];
    }
    throw e;
  }
  const output = ((res.stdout || "") + (res.stderr || "")).trim();
  return [res.status, output];
}

function defaultInteractiveRunner(cmd: string[]): number {
  try {
    // 900s: cert generation is fast, but the sudo prompt waits on a human.
    return run(cmd, { stdio: "inherit", timeout: 900 }).status;
  } catch (e) {
    if (e instanceof ProcError) {
      return e.code === "ENOENT" ? 127 : e.code === "ETIMEDOUT" ? 124 : e.status;
    }
    throw e;
  }
}

function readJson(p: string): Record<string, any> | null {
  let data: unknown;
  try {
    data = JSON.parse(fs.readFileSync(p, "utf8"));
  } catch {
    return null;
  }
  return typeof data === "object" && data !== null && !Array.isArray(data)
    ? (data as Record<string, any>)
    : null;
}

/** The marketplace registry, `{}` when absent/unreadable (fresh machine). */
export function knownMarketplaces(claudePluginsDir: string): Record<string, any> {
  return readJson(path.join(claudePluginsDir, "known_marketplaces.json")) || {};
}

/** The installed version of *spec*, or null when not installed. */
export function installedVersion(claudePluginsDir: string, spec: PluginSpec): string | null {
  const registry = readJson(path.join(claudePluginsDir, "installed_plugins.json")) || {};
  const plugins = registry["plugins"];
  if (typeof plugins !== "object" || plugins === null || Array.isArray(plugins)) {
    return null;
  }
  const entries = plugins[`${spec.name}@${spec.marketplace}`];
  if (!Array.isArray(entries)) {
    return null;
  }
  for (const entry of entries) {
    if (
      typeof entry === "object" &&
      entry !== null &&
      !Array.isArray(entry) &&
      entry["installPath"]
    ) {
      return String(entry["version"] || "unknown");
    }
  }
  return null;
}

/**
 * Converge one plugin: marketplace add/update, then install/update.
 *
 * *driftProbe* (sandbox-tools only) returns plugin_check warnings; after a
 * fix-mode update it distinguishes "converged" from "the marketplace itself
 * lags the local repo" (e.g. local commits not pushed).
 */
export function syncPlugin(
  spec: PluginSpec,
  claudePluginsDir: string,
  runner: Runner,
  checkOnly: boolean,
  driftProbe?: (() => string[]) | null,
): Step[] {
  const label = `plugin ${spec.name}`;
  const version = installedVersion(claudePluginsDir, spec);
  const marketplaceKnown = spec.marketplace in knownMarketplaces(claudePluginsDir);

  if (checkOnly) {
    if (!marketplaceKnown) {
      return [
        {
          label,
          ok: false,
          detail: `marketplace ${spec.marketplace} not added (source: ${spec.source})`,
        },
      ];
    }
    if (version === null) {
      return [{ label, ok: false, detail: `not installed from marketplace ${spec.marketplace}` }];
    }
    const drift = driftProbe ? driftProbe() : [];
    if (drift.length) {
      return [{ label, ok: false, detail: drift.join("; ") }];
    }
    return [{ label, ok: true, detail: `installed v${version}` }];
  }

  const steps: Step[] = [];
  if (marketplaceKnown) {
    const [rc, out] = runner(["claude", "plugin", "marketplace", "update", spec.marketplace]);
    if (rc !== 0) {
      steps.push({ label, ok: false, detail: `marketplace update failed: ${out}` });
    }
  } else {
    const [rc, out] = runner(["claude", "plugin", "marketplace", "add", spec.source]);
    if (rc !== 0) {
      return [{ label, ok: false, detail: `marketplace add (${spec.source}) failed: ${out}` }];
    }
    steps.push({
      label,
      ok: true,
      detail: `added marketplace ${spec.marketplace} (${spec.source})`,
    });
  }

  if (version === null) {
    const [rc, out] = runner(["claude", "plugin", "install", `${spec.name}@${spec.marketplace}`]);
    steps.push({
      label,
      ok: rc === 0,
      detail: rc === 0 ? "installed" : `install failed: ${out}`,
    });
  } else {
    const [rc, out] = runner(["claude", "plugin", "update", `${spec.name}@${spec.marketplace}`]);
    if (rc !== 0) {
      steps.push({ label, ok: false, detail: `update failed: ${out}` });
    } else if (driftProbe?.().length) {
      steps.push({
        label,
        ok: false,
        detail:
          "updated, but the install still lags this repo — are your " + "changes pushed to GitHub?",
      });
    } else {
      steps.push({ label, ok: true, detail: `up to date (was v${version})` });
    }
  }
  return steps;
}

/**
 * Converge an OPTIONAL plugin, which is only installed on an explicit yes.
 *
 * Three cases, and the first is the one that matters: absent and not asked for
 * is `ok`, never a warning. Nothing in the sandbox references these plugins, so
 * reporting a decline as drift would make `--check` fail forever on any machine
 * that answered no — the same reasoning that makes an absent Telepresence ok.
 *
 * Already-installed is different: it is kept current on every run, prompt or
 * no prompt, because a stale plugin misbehaves rather than degrades. Failures
 * are marked `optional` so they warn instead of failing the run.
 */
export function syncOptionalPlugin(
  spec: PluginSpec,
  claudePluginsDir: string,
  runner: Runner,
  checkOnly: boolean,
  install: boolean,
): Step[] {
  const label = `plugin ${spec.name} (optional)`;
  const installed = installedVersion(claudePluginsDir, spec) !== null;

  if (!installed && (checkOnly || !install)) {
    const why = spec.note ? `; ${spec.note}` : "";
    return [{ label, ok: true, detail: `not installed (opt in via \`sandbox setup\`${why})` }];
  }

  return syncPlugin(spec, claudePluginsDir, runner, checkOnly).map((step) => ({
    ...step,
    label,
    optional: true,
  }));
}

/**
 * Clone one of the companion repos into repos_root, or refresh an existing one.
 *
 * An existing checkout is fetched, and fast-forwarded only when it is clean
 * and on main — worktree source checkouts must never be rebased or reset
 * from here.
 *
 * Every failure is optional: a missing companion repo degrades the setup (see
 * each spec's `missingConsequence`) but never blocks the rest of it.
 */
export function syncRepo(
  reposRoot: string,
  spec: RepoSpec,
  runner: Runner,
  checkOnly: boolean,
): Step[] {
  const dest = path.join(reposRoot, spec.name);
  const label = `repo ${spec.name}`;

  if (!fs.existsSync(dest)) {
    if (checkOnly) {
      return [
        {
          label,
          ok: false,
          optional: true,
          detail: `missing — would clone ${spec.url} into ${dest}`,
        },
      ];
    }
    const [rc, out] = runner(["git", "clone", spec.url, dest]);
    if (rc === 0) {
      return [{ label, ok: true, detail: `cloned into ${dest}` }];
    }
    // "Repository not found" from GitHub is deliberately ambiguous between
    // "private and you're not authenticated" and "does not exist", and both are
    // ordinary states here (the repo may simply not be created yet), so say so
    // rather than dumping git's credential-helper stack trace.
    const notFound = /Repository not found|could not read Username|Authentication failed/i.test(
      out,
    );
    const detail = notFound
      ? `${spec.url} is not reachable — it may not exist yet, or ` +
        "you may not be authenticated to GitHub (`gh auth login`, or check your " +
        `git credential helper). ${spec.missingConsequence}`
      : `clone failed: ${briefOutput(out)}`;
    return [{ label, ok: false, optional: true, detail }];
  }

  if (!fs.existsSync(path.join(dest, ".git"))) {
    return [
      {
        label,
        ok: false,
        detail: `${dest} exists but is not a git checkout — move it aside and rerun`,
      },
    ];
  }

  if (checkOnly) {
    return [{ label, ok: true, detail: `present at ${dest}` }];
  }

  const [rc, out] = runner(["git", "-C", dest, "fetch", "origin"]);
  if (rc !== 0) {
    return [{ label, ok: false, detail: `fetch failed: ${out}` }];
  }

  const [, branch] = runner(["git", "-C", dest, "branch", "--show-current"]);
  const [, dirty] = runner(["git", "-C", dest, "status", "--porcelain"]);
  if (branch.trim() !== "main" || dirty.trim()) {
    const why =
      branch.trim() !== "main"
        ? `on branch ${branch.trim() || "(detached)"}`
        : "working tree dirty";
    return [{ label, ok: true, detail: `fetched; skipped fast-forward (${why})` }];
  }

  const [rc2, out2] = runner(["git", "-C", dest, "pull", "--ff-only", "origin", "main"]);
  const detail = rc2 === 0 ? "fetched and fast-forwarded main" : `fast-forward failed: ${out2}`;
  return [{ label, ok: rc2 === 0, detail }];
}

// --- Configured directories (paths.repos_root / paths.workspaces_root) ------

/**
 * Ensure the directories the config names actually exist.
 *
 * The wizard asks where repos and workspaces live, and `check()` then reports
 * drift when those paths are absent — so a first run that answered the prompts
 * would immediately fail its own health check. Creating them here closes that
 * loop: everything downstream (the workspace-repo clone, `sandbox workspace`)
 * assumes both directories are present.
 */
export function syncPathDirs(
  checkOnly: boolean,
  dirs: { repos_root?: string; workspaces_root?: string },
): Step[] {
  const steps: Step[] = [];
  for (const [key, value] of Object.entries(dirs)) {
    if (!value) continue;
    const target = expandUser(value);
    const label = `paths.${key}`;
    if (fs.existsSync(target)) {
      if (!fs.statSync(target).isDirectory()) {
        steps.push({ label, ok: false, detail: `${target} exists but is not a directory` });
      } else {
        steps.push({ label, ok: true, detail: target });
      }
      continue;
    }
    if (checkOnly) {
      steps.push({ label, ok: false, detail: `missing — would create ${target}` });
      continue;
    }
    try {
      fs.mkdirSync(target, { recursive: true });
      steps.push({ label, ok: true, detail: `created ${target}` });
    } catch (e) {
      steps.push({ label, ok: false, detail: `could not create ${target}: ${e}` });
    }
  }
  return steps;
}

// --- Registry configs (~/.sandbox/{services,ports,model-pricing}.yaml) ------

/** Where the registry files used to live, relative to the repo root. */
export const LEGACY_CONFIG_DIR = path.join("infra", "config");

export interface RegistryOptions {
  /** `k8s_context` written into a freshly seeded services.local.yaml. */
  k8sContext?: string;
  /** Legacy `<repo>/infra/config` to migrate from; null disables migration. */
  legacyDir?: string | null;
}

/**
 * Seed the machine-global registry files (ports, pricing, the local overlay),
 * migrating an old checkout's copies. services.yaml is NOT seeded here: it is
 * generated from repo fragments by syncRegistry, after the clone steps.
 *
 * Three outcomes per file, all idempotent:
 *   * present  — already in ~/.sandbox, left untouched (hand edits are safe);
 *   * migrated — found under the checkout's legacy `infra/config/`, COPIED up
 *     (copied, not moved: an old checkout may still be on a branch that needs
 *     the file, and a copy is the reversible choice);
 *   * created  — written fresh from lib/scaffold.
 *
 * These files are the reason `sandbox up` can run at all, so in check mode a
 * missing one is a hard failure rather than a hint.
 */
export function syncRegistryConfigs(checkOnly: boolean, options: RegistryOptions = {}): Step[] {
  const legacyDir =
    options.legacyDir === undefined
      ? path.join(sandboxRoot(), LEGACY_CONFIG_DIR)
      : options.legacyDir;

  // [label, destination, legacy basename (null = never migrated), content factory]
  const files: [string, string, string | null, () => string][] = [
    [
      "services.local.yaml",
      servicesLocalYamlPath(),
      null,
      () => renderServicesLocalYaml(options.k8sContext ?? "orbstack"),
    ],
    ["ports.yaml", portsYamlPath(), "ports.yaml", () => DEFAULT_PORTS_YAML],
    [
      "model-pricing.yaml",
      modelPricingYamlPath(),
      "model-pricing.yaml",
      () => DEFAULT_MODEL_PRICING_YAML,
    ],
  ];

  const steps: Step[] = [];
  for (const [name, dest, legacyName, content] of files) {
    const label = `config ${name}`;
    if (fs.existsSync(dest)) {
      steps.push({ label, ok: true, detail: `present at ${dest}` });
      continue;
    }
    const legacy = legacyDir && legacyName ? path.join(legacyDir, legacyName) : null;
    const migratable = Boolean(legacy && fs.existsSync(legacy));

    if (checkOnly) {
      steps.push({
        label,
        ok: false,
        detail: migratable
          ? `missing — would migrate ${legacy} to ${dest}`
          : `missing — would create ${dest}`,
      });
      continue;
    }

    try {
      if (migratable) {
        fs.mkdirSync(path.dirname(dest), { recursive: true });
        fs.copyFileSync(legacy!, dest);
        steps.push({ label, ok: true, detail: `migrated from ${legacy}` });
      } else {
        const result = seedFile(dest, content());
        steps.push({ label, ok: true, detail: `created ${result.path}` });
      }
    } catch (e) {
      steps.push({ label, ok: false, detail: `could not write ${dest}: ${e}` });
    }
  }

  // secrets.env is a template of empty keys — `sandbox up` validates it and
  // names what's unfilled, so seeding it is a convenience, not a prerequisite.
  const label = "config secrets.env";
  const secrets = secretsPath();
  if (fs.existsSync(secrets)) {
    steps.push({ label, ok: true, detail: `present at ${secrets}` });
  } else if (checkOnly) {
    steps.push({ label, ok: true, detail: `absent — would write a template to ${secrets}` });
  } else {
    try {
      // 0600: this file holds live credentials once filled in.
      const result: SeedResult = seedFile(secrets, renderSecretsEnv(), 0o600);
      steps.push({
        label,
        ok: true,
        detail: `created ${result.path} — fill in the values before \`sandbox up\``,
      });
    } catch (e) {
      steps.push({ label, ok: false, detail: `could not write ${secrets}: ${e}` });
    }
  }

  return steps;
}

// --- TLS certificates for the ingress hostnames -----------------------------

/**
 * Locate `bin/generate-certs.sh`, walking up from the CLI package root.
 *
 * `sandboxRoot()` resolves to the CLI package (`<monorepo>/apps/cli`), but
 * `bin/` sits at the MONOREPO root — so joining the two misses by two levels.
 * Walk instead of hardcoding `../..`, so this keeps working if the CLI is
 * relocated within the monorepo.
 */
export function resolveCertScript(startDir?: string): string | null {
  let dir = startDir ?? sandboxRoot();
  for (let i = 0; i < 5; i++) {
    const candidate = path.join(dir, "bin", "generate-certs.sh");
    if (fs.existsSync(candidate)) {
      return candidate;
    }
    const parent = path.dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }
  return null;
}

export interface CertOptions {
  /** Hostnames the certificate must cover (from `ingressHostnames()`). */
  hostnames: string[];
  ingress?: IngressSettings;
  /** Override `bin/generate-certs.sh` (tests). */
  scriptPath?: string;
  /** Skip the keychain-trust and /etc/hosts steps, which need sudo. */
  skipSudo?: boolean;
}

/**
 * Generate (or verify) the self-signed cert Caddy serves for every ingress host.
 *
 * Delegates entirely to `bin/generate-certs.sh` — the script owns the openssl
 * invocation, the keychain trust and the /etc/hosts reconciliation, and is
 * runnable standalone. This step's job is to hand it the hostname list derived
 * from the registry, so the SANs can't drift from what Caddy actually routes.
 *
 * Skipped as ok when no service declares a `feature_router:` — a machine with
 * no ingress needs no certificate.
 */
export function syncIngressCerts(
  checkOnly: boolean,
  options: CertOptions,
  interactive?: InteractiveRunner | null,
): Step[] {
  const label = "ingress certificate";
  const { hostnames } = options;

  if (!hostnames.length) {
    return [
      {
        label,
        ok: true,
        detail:
          "no routed services — nothing to certify (add a `feature_router:` " +
          "block in services.yaml to enable ingress)",
      },
    ];
  }

  const script = options.scriptPath ?? resolveCertScript();
  if (!script) {
    return [
      {
        label,
        ok: false,
        detail: "bin/generate-certs.sh not found — is the sandbox checkout complete?",
      },
    ];
  }

  const ingress = options.ingress ?? loadIngress();
  const domainArgs = hostnames.flatMap((h) => ["--domain", h]);
  const base = ["bash", script, "--certs-dir", ingress.certs_dir, ...domainArgs];

  if (checkOnly) {
    // --check writes nothing, so the captured runner is right here.
    const [rc, out] = defaultRunner([...base, "--check"]);
    return [
      {
        label,
        ok: rc === 0,
        detail:
          rc === 0
            ? `${ingress.certs_dir}/localhost.crt covers ${hostnames.length} hostname(s)`
            : `${out.trim() || `exit ${rc}`} — run \`sandbox setup\` to (re)generate`,
      },
    ];
  }

  const cmd = [...base];
  if (options.skipSudo) {
    cmd.push("--no-trust", "--no-hosts");
  }
  const rc = (interactive ?? defaultInteractiveRunner)(cmd);
  if (rc !== 0) {
    return [{ label, ok: false, detail: `generate-certs.sh failed (exit ${rc})` }];
  }
  const detail =
    `${ingress.certs_dir} covers ${hostnames.join(", ")}` +
    (options.skipSudo ? " (trust + /etc/hosts skipped — rerun without --yes)" : "");
  return [{ label, ok: true, detail }];
}

// --- Jira API token (optional fast path; `jira:` in ~/.sandbox/config.yaml) --

export const JIRA_TOKEN_URL = "https://id.atlassian.com/manage-profile/security/api-tokens";

/** The `jira:` keys the REST fast path needs, and the paste-me placeholders. */
const JIRA_REQUIRED_KEYS = ["base_url", "email", "api_token"] as const;

/** Copy-pasteable stanza for the report when the section is missing. */
export const JIRA_CONFIG_SNIPPET =
  "jira:\n" +
  "  base_url: https://your-org.atlassian.net\n" +
  "  email: <your-atlassian-login-email>\n" +
  "  api_token: PASTE_TOKEN_HERE";

// A token verifier: the config's jira settings in, [ok, detail] out. Injected in
// tests; the default hits GET /rest/api/2/myself with Basic auth. Async because
// Node has no sync HTTP client.
export type JiraVerifier = (jira: JiraSettings) => Promise<[boolean, string]> | [boolean, string];

async function defaultJiraVerifier(jira: JiraSettings): Promise<[boolean, string]> {
  let baseUrl = (jira.base_url ?? "").trim();
  while (baseUrl.endsWith("/")) baseUrl = baseUrl.slice(0, -1);
  const auth = Buffer.from(`${jira.email}:${jira.api_token}`).toString("base64");
  try {
    const resp = await fetch(`${baseUrl}/rest/api/2/myself`, {
      headers: { Authorization: `Basic ${auth}` },
      signal: AbortSignal.timeout(10_000),
    });
    if (!resp.ok) {
      return [false, `HTTP ${resp.status}`];
    }
    const who = ((await resp.json()) as Record<string, any>)["displayName"] || jira.email;
    return [true, `authenticated as ${who}`];
  } catch (e) {
    // network down, bad URL, timeout — all one story
    return [false, String(e instanceof Error ? e.message : e)];
  }
}

/**
 * Report the optional Jira REST credentials from `jira:` in the global config.
 *
 * Absent or unfilled is ok-with-guidance (the fast path is an optimization —
 * everything falls back to the claude CLI). Fix mode live-verifies a filled
 * token; only a rejected token is a failure. Nothing to converge — the token is
 * hand-pasted — so this step never writes.
 */
export async function syncJiraToken(
  jira: JiraSettings,
  checkOnly: boolean,
  verifier?: JiraVerifier | null,
): Promise<Step[]> {
  const label = "jira token (optional)";
  const where = configPath();

  const unfilled = JIRA_REQUIRED_KEYS.filter((k) => {
    const value = (jira[k] ?? "").trim();
    return !value || JIRA_PLACEHOLDERS.has(value);
  });
  if (unfilled.length) {
    const keys = unfilled.map((k) => `jira.${k}`).join(", ");
    return [
      {
        label,
        ok: true,
        detail:
          `not configured (${keys}) — create a token at ${JIRA_TOKEN_URL}, ` +
          `then add it to ${where}:\n${JIRA_CONFIG_SNIPPET}`,
      },
    ];
  }

  if (checkOnly) {
    return [
      {
        label,
        ok: true,
        detail: `configured for ${jira.email} (run \`sandbox setup\` to live-verify)`,
      },
    ];
  }

  const [ok, detail] = await (verifier ?? defaultJiraVerifier)(jira);
  if (ok) {
    return [{ label, ok: true, detail }];
  }
  // Optional: the dashboard falls back to the claude CLI for Jira reads, so a
  // rejected token degrades one fast path — it does not break the machine.
  return [
    {
      label,
      ok: false,
      optional: true,
      detail:
        `token rejected (${detail}) — renew at ${JIRA_TOKEN_URL} and update ` +
        `jira.api_token in ${where}. Reads fall back to the claude CLI meanwhile.`,
    },
  ];
}

/** Schema file in `<cli>/infra/schemas/` → the glob it validates. */
const EDITOR_SCHEMAS: Record<string, string> = {
  "services-fragment.schema.json": "**/.sandbox/services.yaml",
  "workspace.schema.json": "**/.sandbox/workspace.yml",
};

/** VS Code's user settings.json (stable channel only). */
export function vscodeSettingsPath(): string {
  return process.platform === "darwin"
    ? path.join(os.homedir(), "Library", "Application Support", "Code", "User", "settings.json")
    : path.join(os.homedir(), ".config", "Code", "User", "settings.json");
}

export interface EditorSchemaState {
  /** VS Code's user dir exists. */
  present: boolean;
  /** Unparsable settings.json; its parse error. */
  error?: string;
  /** `yaml.schemas` keys to set (schema path → glob) and to drop (stale paths). */
  set: Record<string, string>;
  drop: string[];
  /** Raw settings text the edits apply to. */
  text: string;
}

/**
 * What `yaml.schemas` in VS Code's user settings lacks for the sandbox schemas.
 *
 * The schemas are mapped by local path, not URL: the repo is private, so
 * raw.githubusercontent.com 404s for an editor. A mapping for one of our globs
 * that names some other file is stale (an old install path) and is dropped.
 */
export function editorSchemaState(
  settingsPath = vscodeSettingsPath(),
  schemasDir = path.join(sandboxRoot(), "infra", "schemas"),
): EditorSchemaState {
  const state: EditorSchemaState = { present: false, set: {}, drop: [], text: "{}" };
  if (!fs.existsSync(path.dirname(settingsPath))) return state;
  state.present = true;
  if (fs.existsSync(settingsPath)) state.text = fs.readFileSync(settingsPath, "utf8");
  const errors: ParseError[] = [];
  const data = parseJsonc(state.text, errors, { allowTrailingComma: true });
  if (errors.length) {
    state.error = `parse error at offset ${errors[0].offset}`;
    return state;
  }
  const mapped: Record<string, unknown> = data?.["yaml.schemas"] ?? {};
  const covers = (v: unknown, glob: string) => v === glob || (Array.isArray(v) && v.includes(glob));
  for (const [file, glob] of Object.entries(EDITOR_SCHEMAS)) {
    const want = path.join(schemasDir, file);
    if (!covers(mapped[want], glob)) state.set[want] = glob;
    for (const [key, v] of Object.entries(mapped)) {
      if (key !== want && covers(v, glob)) state.drop.push(key);
    }
  }
  return state;
}

/**
 * Map the sandbox YAML schemas in VS Code's user settings (redhat.vscode-yaml).
 *
 * Optional, and a user-owned file: writes only when the wizard asked and the
 * user said yes (`install`). Edits go through jsonc-parser so comments and
 * formatting in settings.json survive.
 */
export function syncEditorSchemas(
  checkOnly: boolean,
  install: boolean,
  settingsPath = vscodeSettingsPath(),
  schemasDir?: string,
): Step[] {
  const label = "VS Code YAML schemas (optional)";
  const state = editorSchemaState(settingsPath, schemasDir);
  if (!state.present) return [{ label, ok: true, detail: "VS Code not found — skipped" }];
  if (state.error) {
    return [
      {
        label,
        ok: false,
        optional: true,
        detail: `${settingsPath}: ${state.error} — fix it and re-run`,
      },
    ];
  }
  const pending = Object.keys(state.set).length + state.drop.length;
  if (!pending) return [{ label, ok: true, detail: `mapped in ${settingsPath}` }];
  if (checkOnly || !install) {
    return state.drop.length
      ? [
          {
            label,
            ok: false,
            optional: true,
            detail: "mapped to an old install path — re-run `sandbox setup`",
          },
        ]
      : [{ label, ok: true, detail: "not mapped (opt in via `sandbox setup`)" }];
  }
  let text = state.text;
  const fmt = { formattingOptions: { insertSpaces: true, tabSize: 4 } };
  for (const key of state.drop)
    text = applyEdits(text, modify(text, ["yaml.schemas", key], undefined, fmt));
  for (const [key, glob] of Object.entries(state.set)) {
    text = applyEdits(text, modify(text, ["yaml.schemas", key], glob, fmt));
  }
  fs.writeFileSync(settingsPath, text);
  return [{ label, ok: true, optional: true, detail: `mapped in ${settingsPath}` }];
}

/** Claude Code's user settings.json. */
export function claudeUserSettingsPath(): string {
  return path.join(os.homedir(), ".claude", "settings.json");
}

export interface ClaudeStandardsDirState {
  /** `~/.claude/` exists. */
  present: boolean;
  /** The standards dir does not exist. */
  dirMissing: boolean;
  /** Unparsable settings.json, or `permissions.additionalDirectories` that isn't an array. */
  error?: string;
  /** An `additionalDirectories` entry already resolves to the standards dir. */
  granted: boolean;
  /** Raw settings text the edit applies to. */
  text: string;
}

/**
 * Whether Claude Code may read the standards dir without a prompt.
 *
 * Every stage contract points the agent at the standards, which live outside
 * any workspace; a grant in the user settings covers every session on the
 * machine, and keeps the machine path out of the portable workspace record.
 */
export function claudeStandardsDirState(
  settingsPath = claudeUserSettingsPath(),
  dir = standardsDirPath(),
): ClaudeStandardsDirState {
  const state: ClaudeStandardsDirState = {
    present: false,
    dirMissing: false,
    granted: false,
    text: "{}",
  };
  state.present = fs.existsSync(path.dirname(settingsPath));
  state.dirMissing = !(fs.existsSync(dir) && fs.statSync(dir).isDirectory());
  if (!state.present || state.dirMissing) return state;
  if (fs.existsSync(settingsPath)) state.text = fs.readFileSync(settingsPath, "utf8");
  const errors: ParseError[] = [];
  const data = parseJsonc(state.text, errors, { allowTrailingComma: true });
  if (errors.length) {
    state.error = `parse error at offset ${errors[0].offset}`;
    return state;
  }
  const dirs = data?.["permissions"]?.["additionalDirectories"];
  if (dirs !== undefined && !Array.isArray(dirs)) {
    state.error = "permissions.additionalDirectories is not an array";
    return state;
  }
  const want = path.resolve(dir);
  state.granted = (dirs ?? []).some((d: unknown) => path.resolve(expandUser(String(d))) === want);
  return state;
}

/**
 * Grant Claude Code read access to the standards dir in its user settings.
 *
 * Optional, and a user-owned file: writes only when the wizard asked and the
 * user said yes (`install`). Edits go through jsonc-parser so comments and
 * formatting in settings.json survive.
 */
export function syncClaudeStandardsDir(
  checkOnly: boolean,
  install: boolean,
  settingsPath = claudeUserSettingsPath(),
  dir = standardsDirPath(),
): Step[] {
  const label = "Claude Code standards access (optional)";
  const state = claudeStandardsDirState(settingsPath, dir);
  if (!state.present)
    return [{ label, ok: true, detail: "Claude Code settings dir not found — skipped" }];
  if (state.dirMissing)
    return [{ label, ok: true, detail: `standards dir ${dir} not found — skipped` }];
  if (state.error) {
    return [
      {
        label,
        ok: false,
        optional: true,
        detail: `${settingsPath}: ${state.error} — fix it and re-run`,
      },
    ];
  }
  if (state.granted) return [{ label, ok: true, detail: `granted in ${settingsPath}` }];
  if (checkOnly || !install)
    return [{ label, ok: true, detail: "not granted (opt in via `sandbox setup`)" }];
  const fmt = { formattingOptions: { insertSpaces: true, tabSize: 2 } };
  const hasList = Array.isArray(
    parseJsonc(state.text, [], { allowTrailingComma: true })?.["permissions"]?.[
      "additionalDirectories"
    ],
  );
  // ponytail: add-only — a grant left by an old standards_dir stays; record the granted path under ~/.sandbox if stale grants ever matter.
  const edits = hasList
    ? modify(state.text, ["permissions", "additionalDirectories", -1], dir, {
        ...fmt,
        isArrayInsertion: true,
      })
    : modify(state.text, ["permissions", "additionalDirectories"], [dir], fmt);
  fs.writeFileSync(settingsPath, applyEdits(state.text, edits));
  return [{ label, ok: true, optional: true, detail: `granted in ${settingsPath}` }];
}

/** `<publisher>.<name>` from packages/vscode-plugin/package.json, as `code` lists it. */
export const VSCODE_EXTENSION_ID = "jbbz.vscode-plugin";
/** Where the CLI's `prepack` puts the packaged extension inside the tarball. */
export const BUNDLED_VSIX_REL = path.join("dist", "sandbox-workspaces.vsix");

export interface VscodeExtensionState {
  /** The `code` CLI answered. */
  cli: boolean;
  /** Installed extension version, or null. */
  installed: string | null;
  /**
   * The .vsix shipped in the published CLI package, at the CLI's own version
   * (the changeset `fixed` group keeps the two equal). Null in a checkout:
   * only `prepack` builds it, so a dev's local build is never installed.
   */
  bundled: { path: string; version: string } | null;
}

export function vscodeExtensionState(
  runner: Runner = defaultRunner,
  root = sandboxRoot(),
): VscodeExtensionState {
  const [rc, out] = runner(["code", "--list-extensions", "--show-versions"]);
  const prefix = `${VSCODE_EXTENSION_ID}@`;
  const line =
    rc === 0 ? out.split("\n").find((l) => l.trim().toLowerCase().startsWith(prefix)) : undefined;
  const vsix = path.join(root, BUNDLED_VSIX_REL);
  return {
    cli: rc === 0,
    installed: line ? line.trim().slice(prefix.length) : null,
    bundled: fs.existsSync(vsix)
      ? { path: vsix, version: readJson(path.join(root, "package.json"))?.version }
      : null,
  };
}

/**
 * Install the Sandbox Workspaces extension from the .vsix the published CLI
 * ships. Optional: only when the wizard asked and the answer was yes.
 */
export function syncVscodeExtension(
  checkOnly: boolean,
  install: boolean,
  state = vscodeExtensionState(),
  runner: Runner = defaultRunner,
): Step[] {
  const label = "VS Code extension (optional)";
  if (!state.cli) {
    return [
      {
        label,
        ok: true,
        detail:
          "`code` not on PATH — skipped (in VS Code: \"Shell Command: Install 'code' command in PATH\")",
      },
    ];
  }
  if (!state.bundled) {
    return [
      {
        label,
        ok: true,
        detail: `${state.installed ?? "not installed"}; running from a checkout, which bundles no .vsix — build it from packages/vscode-plugin`,
      },
    ];
  }
  const want = state.bundled.version;
  if (state.installed === want)
    return [{ label, ok: true, detail: `${VSCODE_EXTENSION_ID} ${want}` }];
  if (checkOnly || !install) {
    return state.installed
      ? [
          {
            label,
            ok: false,
            optional: true,
            detail: `${state.installed} < bundled ${want} — re-run \`sandbox setup\``,
          },
        ]
      : [{ label, ok: true, detail: "not installed (opt in via `sandbox setup`)" }];
  }
  const [rc, out] = runner(["code", "--install-extension", state.bundled.path, "--force"]);
  if (rc !== 0) {
    return [
      {
        label,
        ok: false,
        optional: true,
        detail: `code --install-extension failed: ${briefOutput(out)}`,
      },
    ];
  }
  return [
    {
      label,
      ok: true,
      detail: `installed ${VSCODE_EXTENSION_ID} ${want} — reload VS Code windows to pick it up`,
    },
  ];
}

/**
 * Report — and optionally install via Homebrew — the Telepresence OSS client.
 *
 * Optional prerequisite: only `sandbox intercept` needs it, so absence is
 * ok=true with a hint rather than a failure. Installation only happens when the
 * caller passes `install: true` (the setup wizard asks first); check mode never
 * installs. An installed-but-stale client is ok=false either way, because
 * `intercept` will misbehave rather than degrade on a version below MIN_VERSION.
 */
export function syncTelepresence(
  runner: Runner,
  checkOnly: boolean,
  options: { install?: boolean } = {},
): Step[] {
  const label = "telepresence (optional)";
  const need = MIN_VERSION.join(".");

  /** Probe the client: [step-or-null, parsed version]. */
  const probe = (): [Step | null, [number, number, number] | null] => {
    const [rc, out] = runner(["telepresence", "version"]);
    if (rc !== 0) {
      return [null, null];
    }
    const version = parseVersion(out);
    if (version === null) {
      return [
        { label, ok: false, optional: true, detail: `version unparseable: ${out.slice(0, 80)}` },
        null,
      ];
    }
    return [null, version];
  };

  const [probeErr, version] = probe();
  if (probeErr) {
    return [probeErr];
  }

  if (version && !versionLt(version, MIN_VERSION)) {
    return [{ label, ok: true, detail: `OSS client ${version.join(".")}` }];
  }

  const stale = version !== null;
  const current = stale ? `${version!.join(".")} < required ${need}` : "not installed";

  if (checkOnly || !options.install) {
    if (stale) {
      return [{ label, ok: false, optional: true, detail: `${current} — ${INSTALL_HINT}` }];
    }
    return [
      {
        label,
        ok: true,
        detail: `not installed (needed only for \`sandbox intercept\`; ${INSTALL_HINT})`,
      },
    ];
  }

  // Install requested. brew is the happy path; anything else falls back to the
  // documented direct download rather than trying to be clever.
  const [brewRc] = runner(["brew", "--version"]);
  if (brewRc !== 0) {
    return [
      {
        label,
        ok: !stale,
        optional: true,
        detail: `${current}; Homebrew not found — ${DOWNLOAD_HINT}`,
      },
    ];
  }

  const action = stale ? "upgrade" : "install";
  const [rc, out] = runner(["brew", action, BREW_FORMULA]);
  if (rc !== 0) {
    return [
      {
        label,
        ok: false,
        optional: true,
        detail:
          `brew ${action} ${BREW_FORMULA} failed: ${briefOutput(out)}\n` +
          `    Telepresence stays optional — this does not block anything except ` +
          `\`sandbox intercept\`. Install manually with: ${DOWNLOAD_HINT}`,
      },
    ];
  }

  // Verify rather than trust: the whole reason brew was previously rejected is
  // that a tap can ship a version below MIN_VERSION.
  const [postErr, postVersion] = probe();
  if (postErr) {
    return [postErr];
  }
  if (postVersion === null) {
    return [
      {
        label,
        ok: false,
        optional: true,
        detail: `brew ${action} reported success but telepresence is not on PATH`,
      },
    ];
  }
  const have = postVersion.join(".");
  if (versionLt(postVersion, MIN_VERSION)) {
    return [
      {
        label,
        ok: false,
        optional: true,
        detail: `brew installed ${have}, still < required ${need} — ${DOWNLOAD_HINT}`,
      },
    ];
  }
  return [{ label, ok: true, detail: `installed OSS client ${have} via brew` }];
}

/**
 * Install the Chromium build the pinned Playwright expects — each release wants
 * one exact revision, so a cache holding another one fails at launch (sandbox#99).
 */
export function syncPlaywright(
  runner: Runner,
  checkOnly: boolean,
  interactive?: InteractiveRunner | null,
): Step[] {
  const label = "playwright chromium (optional)";
  const pkg = `playwright@${PLAYWRIGHT_VERSION}`;

  // Playwright's own --dry-run names the directories, so its cache-path rules
  // (macOS vs Linux, PLAYWRIGHT_BROWSERS_PATH) stay its problem, not ours.
  let probeOutput = "";
  const missingDirs = (): string[] | null => {
    const [rc, out] = runner(["npx", "-y", pkg, "install", "--dry-run", "chromium"]);
    probeOutput = out;
    const dirs = [...out.matchAll(/Install location:\s*(\S.*)$/gm)].map((m) => m[1]!.trim());
    // No locations parsed means the output format moved, not that nothing is needed.
    if (rc !== 0 || dirs.length === 0) return null;
    // A partial download leaves the directory but not Playwright's completion marker.
    return dirs.filter((d) => !fs.existsSync(path.join(d, "INSTALLATION_COMPLETE")));
  };

  const before = missingDirs();
  if (before === null) {
    return [
      {
        label,
        ok: false,
        optional: true,
        detail: `\`npx ${pkg} install --dry-run chromium\` failed: ${briefOutput(probeOutput)}`,
      },
    ];
  }
  if (before.length === 0) {
    return [{ label, ok: true, detail: `chromium for ${pkg} present` }];
  }
  if (checkOnly) {
    return [
      {
        label,
        ok: false,
        optional: true,
        detail: `chromium for ${pkg} missing — re-run \`sandbox setup\``,
      },
    ];
  }

  // Interactive: the download is ~150 MB, so show progress rather than look hung.
  const rc = (interactive ?? defaultInteractiveRunner)(["npx", "-y", pkg, "install", "chromium"]);
  const after = missingDirs();
  if (rc !== 0 || after === null || after.length > 0) {
    const why =
      rc !== 0 ? `exited ${rc}` : "finished, but the browser is still not reported installed";
    return [
      {
        label,
        ok: false,
        optional: true,
        detail: `\`npx ${pkg} install chromium\` ${why} — run it manually to see why`,
      },
    ];
  }
  return [{ label, ok: true, detail: `installed chromium for ${pkg}` }];
}

export interface RunSetupOptions {
  checkOnly?: boolean;
  reposRoot?: string | null;
  claudePluginsDir?: string | null;
  repoPluginDir?: string | null;
  runner?: Runner | null;
  interactiveRunner?: InteractiveRunner | null;
  jira?: JiraSettings | null;
  jiraVerifier?: JiraVerifier | null;
  /** Directories to create; defaults to the config's `paths:` section. */
  pathDirs?: { repos_root?: string; workspaces_root?: string };
  /** Registry seeding (k8s context for services.local.yaml, migration source). */
  registry?: RegistryOptions;
  /** The wizard's "clone the demo apps" answer; the repo is also synced when already present. */
  demo?: boolean;
  /** `owner/repo` for the workspace-root checkout; defaults to the config's. */
  workspaceRepo?: string;
  /**
   * Ingress hostnames the certificate must cover; `[]` skips the cert step.
   *
   * Pass a THUNK on a first run: the hostnames come from services.yaml, which
   * may not exist until the registry step earlier in this same run seeds it.
   * The thunk is called after that step, so a fresh machine certifies the
   * hostnames it just created.
   */
  hostnames?: string[] | (() => string[]);
  ingress?: IngressSettings | null;
  /** Skip the sudo-requiring parts of cert setup (trust + /etc/hosts). */
  skipSudo?: boolean;
  /** Install Telepresence via Homebrew when it is missing or stale. */
  installTelepresence?: boolean;
  /** Install the optional plugins (superpowers) when they are missing. */
  installOptionalPlugins?: boolean;
  /** Map the sandbox YAML schemas in VS Code's user settings (the wizard asks first). */
  mapEditorSchemas?: boolean;
  /** Install the bundled Sandbox Workspaces VS Code extension (the wizard asks first). */
  installVscodeExtension?: boolean;
  /** Grant Claude Code read access to the standards dir in its user settings (the wizard asks first). */
  grantStandardsDir?: boolean;
}

/**
 * Sync every machine prerequisite; the full report, ordered as declared.
 *
 * Order matters: the repo clones precede the registry step because the registry
 * is generated from fragments inside those clones, and the cert step follows
 * because it derives its hostname list from the registry.
 */
export async function runSetup(options: RunSetupOptions = {}): Promise<Step[]> {
  const checkOnly = options.checkOnly ?? false;
  const reposRoot = options.reposRoot ?? getReposRoot();
  const claudePluginsDir =
    options.claudePluginsDir ?? path.join(os.homedir(), ".claude", "plugins");
  const repoPluginDir =
    options.repoPluginDir ?? path.join(sandboxRoot(), "plugins", "sandbox-tools");
  const runner = options.runner ?? defaultRunner;
  const jira = options.jira ?? loadJira();

  const steps: Step[] = [];
  // Directories first: the workspace-repo clone below needs reposRoot to exist.
  // Only the two the user configures — `sandbox_root` is the running checkout,
  // self-derived and never ours to create.
  const configuredPaths = options.pathDirs ?? {
    repos_root: loadPathsSection()["repos_root"],
    workspaces_root: loadPathsSection()["workspaces_root"],
  };
  steps.push(...syncPathDirs(checkOnly, configuredPaths));
  steps.push(...syncRegistryConfigs(checkOnly, options.registry ?? {}));

  // Preflight the `claude` CLI once. Without it every plugin step fails with
  // the same "command not found", which reads as N separate problems instead of
  // the one that it is. Note the VS Code extension does NOT put `claude` on
  // PATH — having Claude Code in the editor is not the same as having the CLI.
  const [claudeRc] = runner(["claude", "--version"]);
  if (claudeRc === 127) {
    steps.push({
      label: "claude CLI",
      ok: false,
      detail:
        "not found on PATH — the sandbox-tools and ponytail plugins cannot be " +
        "installed without it. Install Claude Code from " +
        "https://claude.com/claude-code (the VS Code extension alone does not " +
        "put `claude` on PATH), then re-run `sandbox setup`.",
    });
  } else {
    for (const spec of REQUIRED_PLUGINS) {
      let driftProbe: (() => string[]) | null = null;
      if (spec.name === "sandbox-tools") {
        driftProbe = () => pluginDriftWarnings(repoPluginDir, claudePluginsDir);
      }
      steps.push(...syncPlugin(spec, claudePluginsDir, runner, checkOnly, driftProbe));
    }
    for (const spec of OPTIONAL_PLUGINS) {
      steps.push(
        ...syncOptionalPlugin(
          spec,
          claudePluginsDir,
          runner,
          checkOnly,
          options.installOptionalPlugins ?? false,
        ),
      );
    }
  }
  // Fall back to the gh-derived default so a machine configured before this
  // setting existed still converges; only a machine with neither config nor a
  // usable `gh` has no repo to clone, and that is a warning, not a failure.
  const workspaceRepo =
    options.workspaceRepo ?? (loadWorkspaceRepo() || defaultWorkspaceRepo(runner));
  if (workspaceRepo) {
    steps.push(...syncRepo(reposRoot, workspaceRootSpec(workspaceRepo), runner, checkOnly));
  } else {
    steps.push({
      label: `repo ${WORKSPACE_ROOT_REPO}`,
      ok: false,
      optional: true,
      detail:
        "no workspace repo configured and `gh` could not name one — set " +
        "overrides.workspace_repo (or run `gh auth login`, then `sandbox setup`). " +
        "Workspaces will fall back to plain directories.",
    });
  }
  // Gated on the wizard's answer OR on-disk presence. The registry is generated
  // from fragments AFTER this clone (the demo fragment lives in the repo), so
  // it cannot be the gate; presence keeps a `--check` run — which passes no
  // answers — reporting a repo the machine already has.
  if (options.demo || fs.existsSync(path.join(reposRoot, DEMO_SERVICES_REPO))) {
    steps.push(...syncRepo(reposRoot, DEMO_SERVICES_SPEC, runner, checkOnly));
  }
  // Every repo this run can clone is on disk now — generate the registry.
  steps.push(...syncRegistry({ reposRoot, checkOnly }));
  // Resolved here, not at call time — see RunSetupOptions.hostnames.
  const hostnames =
    typeof options.hostnames === "function" ? options.hostnames() : (options.hostnames ?? []);
  steps.push(
    ...syncIngressCerts(
      checkOnly,
      { hostnames, ingress: options.ingress ?? undefined, skipSudo: options.skipSudo },
      options.interactiveRunner,
    ),
  );
  steps.push(...(await syncJiraToken(jira, checkOnly, options.jiraVerifier)));
  steps.push(...syncTelepresence(runner, checkOnly, { install: options.installTelepresence }));
  steps.push(...syncPlaywright(runner, checkOnly, options.interactiveRunner));
  steps.push(...syncEditorSchemas(checkOnly, options.mapEditorSchemas ?? false));
  steps.push(...syncClaudeStandardsDir(checkOnly, options.grantStandardsDir ?? false));
  steps.push(
    ...syncVscodeExtension(
      checkOnly,
      options.installVscodeExtension ?? false,
      vscodeExtensionState(runner),
      runner,
    ),
  );
  return steps;
}
